SELECT
  ZSTARTDATE,
  ZENDDATE,
  ZVALUESTRING
FROM ZOBJECT
WHERE ZSTREAMNAME = '/app/usage'
  AND ZENDDATE >= {{cocoaStart}}
  AND ZSTARTDATE <= {{cocoaEnd}}
ORDER BY ZSTARTDATE;

SELECT
  ZSTARTDATE,
  ZENDDATE,
  ZVALUESTRING
FROM ZOBJECT
WHERE ZSTREAMNAME = '/app/inFocus'
  AND ZENDDATE >= {{cocoaStart}}
  AND ZSTARTDATE <= {{cocoaEnd}}
ORDER BY ZSTARTDATE;

SELECT
  ZSTARTDATE,
  ZENDDATE,
  ZVALUEINTEGER
FROM ZOBJECT
WHERE ZSTREAMNAME = '/display/isBacklit'
  AND ZENDDATE >= {{cocoaStart}}
  AND ZSTARTDATE <= {{cocoaEnd}}
ORDER BY ZSTARTDATE;

SELECT
  ZSTARTDATE,
  ZENDDATE,
  ZVALUEINTEGER
FROM ZOBJECT
WHERE ZSTREAMNAME = '/device/isLocked'
  AND ZENDDATE >= {{cocoaStart}}
  AND ZSTARTDATE <= {{cocoaEnd}}
ORDER BY ZSTARTDATE;
